n", "#text": "cn-standard"}, "cbc:NoticeLanguageCode": "FRA", "cac:ContractingParty": {"cac:ContractingPartyType": [{"cbc:PartyTypeCode": {"@listName": "buyer-legal-type", "#text": "body-pl"}}, {"cbc:PartyTypeCode": {"@listName": "buyer-contracting-type", "#text": "not-cont-ent"}}], "cac:ContractingActivity": {"cbc:ActivityTypeCode": {"@listName": "authority-activity", "#text": "gen-pub"}}, "cac:Party": {"cac:PartyIdentification": {"cbc:ID": {"@schemeName": "organization", "#text": "ORG-0002"}}, "cac:ServiceProviderParty": {"cbc:ServiceTypeCode": {"@listName": "organisation-role", "#text": "ted-esen"}, "cac:Party": {"cac:PartyIdentification": {"cbc:ID": {"@schemeName": "organization", "#text": "ORG-0001"}}}}}}, "cac:TenderingTerms": {"cac:TendererQualificationRequest": {"cac:SpecificTendererRequirement": {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "nati-ground"}, "cbc:Description": {"@languageID": "FRA", "#text": "« Le candidat individuel, ou chaque membre du groupement, ne doit pas entrer dans l’un des cas d’exclusion de la procédure de passation prévus par le code de la commande publique."}}}}, "cac:ProcurementProject": {"cbc:ID": "24AS-0094-H", "cbc:Name": {"@languageID": "FRA", "#text": "Concession avec délégation de service public pour l'exploitation du centre aquatique de la communauté de communes de l'Huisne sarthoise"}, "cbc:Description": {"@languageID": "FRA", "#text": "Le Concessionnaire est responsable de la gestion complète du Service incluant la gestion et l'exploitation commerciale, administrative, financière et technique. Le Concessionnaire assure l'exploitation du Service public concédé au travers des missions suivantes :
- L'exercice des activités suivantes :
- L'organisation de la baignade publique dans les divers bassins prévus à cet effet et leurs espaces annexes intérieurs et extérieurs, praticables pendant les heures d'ouverture au grand public ;
- L'accueil des groupes (scolaires du 1er degré, scolaires du 2nd degré, clubs et associations, centres de loisirs, etc.) pendant les heures réservées à cet effet ;
- L'enseignement et la surveillance des séances pédagogiques à destination des élèves des établissements scolaires du 1er degré, pendant les périodes réservées à cet effet ;
- La surveillance des séances pédagogiques à destination des élèves des établissements scolaires du 2nd degré, pendant les périodes réservées à cet effet ;
- Le développement des activités de détente et de loisir ;
- Le développement des activités aquatiques telles que les cours de natation individuels ou collectifs, assurés directement par le personnel du concessionnaire, les activités de gymnastique aquatique ainsi que toutes autres activités liées à l'usage de l'eau ;
- L'exploitation de l'espace bien-être / fitness
- La gestion du service, des locaux et équipements mis à sa disposition, à savoir :
- La planification globale d'utilisation du site ;
- La gestion technique, administrative, financière et commerciale du Centre aquatique ;
- Le gardiennage des installations
- L'accueil des usagers : organiser et coordonner les activités sportives, ludiques et de loisirs ; surveiller les baigneurs et autres usagers de l'équipement dans les conditions réglementaires et de sécurité en vigueur ;
- L'entretien courant des locaux (intérieur et extérieur), la maintenance et la réparation des biens, équipements, installations et du matériel dans les conditions définies par le présent contrat ;
- L'animation de l'équipement (activités) et l'organisation d'événements propices à la renommée de l'équipement ;
- Le recrutement, la formation et l'encadrement du personnel du concessionnaire et du personnel détaché affecté au service ;
- Le contrôle de l'hygiène, notamment la réalisation de tous les contrôles (en interne ou externalisés) prévus par la réglementation ;
- La perception des droits d'entrée auprès des usagers conformément aux tarifs fixés par la convention de Concession de service public ;
- Assurer la gestion de la relation avec les usagers (enregistrement des réclamations, analyse et proposition de réponse, …)"}, "cbc:ProcurementTypeCode": {"@listName": "contract-nature", "#text": "services"}, "cac:MainCommodityClassification": {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "92610000"}}, "cac:AdditionalCommodityClassification": {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "92610000"}}}, "cac:ProcurementProjectLot": {"cbc:ID": {"@schemeName": "Lot", "#text": "LOT-0000"}, "cac:TenderingTerms": {"ext:UBLExtensions": {"ext:UBLExtension": {"ext:ExtensionContent": {"efext:EformsExtension": {"efac:SelectionCriteria": [{"cbc:CriterionTypeCode": {"@listName": "selection-criterion", "#text": "sui-act"}, "cbc:Description": {"@languageID": "FRA", "#text": "1- Lettre de candidature indiquant l'identité du candidat ou du mandataire du groupement qui précisera l'identité de chaque membre dudit groupement (Dc1 ou équivalent) ;
2- En cas de groupement : habilitation du mandataire par ses cotraitants ;
3- Pouvoir de la personne habilitée à engager le candidat individuel ou chaque membre du groupement ;
4- Déclaration sur l'honneur par laquelle le candidat individuel, ou chaque membre du groupement, atteste :
- qu'il ne fait l'objet d'aucune exclusion de la participation à la procédure de passation des contrats de concession prévues aux articles L3123-1 à L L3123-14 du Code de la commande publique ;- que les renseignements et documents relatifs à ses capacités et aptitudes fournis dans le cadre de la présente consultation sont exacts ;
5- Justificatif de l'inscription du candidat au registre du commerce et des sociétés (extrait K bis ou document d'effet équivalent) datant de moins de 3 mois ;
6- Certificats et déclarations fiscales et sociales, délivrés par les administrations et organismes compétents justifiant que le candidat ou que chaque membre du groupement candidat a satisfait à ses obligations sociales, fiscales et d'emploi des travailleurs handicapés ;
7- Si le candidat est en procédure de sauvegarde, redressement judiciaire, la copie du ou des jugements prononcés à cet effet (ou leurs équivalents pour les candidats étrangers non établis en France) ainsi qu'une note démontrant qu'il est en mesure d'exécuter le contrat de concession compte tenu des règles applicables en matière de poursuite des activités dans le cadre de ces situations"}, "cbc:CalculationExpressionCode": {"@listName": "usage", "#text": "used"}}, {"cbc:CriterionTypeCode": {"@listName": "selection-criterion", "#text": "ef-stand"}, "cbc:Description": {"@languageID": "FRA", "#text": "11- Les comptes de résultat et bilans des trois derniers exercices ;
12- Tout document complémentaire de nature à faire apparaître la capacité et la solidité financière du candidat. Les candidats qui ne seraient pas constitués depuis plus de trois ans pourront faire la preuve de leur capacité économique et financière par tout moyen"}, "cbc:CalculationExpressionCode": {"@listName": "usage", "#text": "used"}}, {"cbc:CriterionTypeCode": {"@listName": "selection-criterion", "#text": "tp-abil"}, "cbc:Description": {"@languageID": "FRA", "#text": "8- Références du candidat de moins de dix ans dans le domaine d'activité faisant l'objet de la délégation, indiquant notamment l'autorité délégante, le montant et la date du contrat (date de prise d'effet et date d'échéance) ;
9- Moyens humains et techniques dont le candidat disposera pour l'exploitation du présent service délégué ;
10- Note de présentation générale du candidat et de son savoir-faire permettant d'apprécier son aptitude à assurer la continuité du service public ainsi que l'égalité des usagers devant celui-ci"}, "cbc:CalculationExpressionCode": {"@listName": "usage", "#text": "used"}}]}}}}, "cbc:VariantConstraintCode": {"@listName": "permission", "#text": "not-allowed"}, "cbc:FundingProgramCode": {"@listName": "eu-funded", "#text": "no-eu-funds"}, "cbc:RecurringProcurementIndicator": "true", "cac:CallForTendersDocumentReference": {"cbc:ID": "1450289", "cbc:DocumentType": "non-restricted-document", "cbc:LanguageID": "FRA", "cbc:DocumentStatusCode": {"@listName": "linguistic-status", "#text": "official"}, "cac:Attachment": {"cac:ExternalReference": {"cbc:URI": "https://www.marches-publics.info/mpiaws/index.cfm?fuseaction=dematEnt.login&amp;type=DCE&amp;IDM=1450289"}}}, "cac:TendererQualificationRequest": {"cac:SpecificTendererRequirement": {"cbc:TendererRequirementTypeCode": {"@listName": "reserved-procurement", "#text": "none"}}}, "cac:ContractExecutionRequirement": [{"cbc:ExecutionRequirementCode": {"@listName": "einvoicing", "#text": "required"}}, {"cbc:ExecutionRequirementCode": {"@listName": "esignature-submission", "#text": "false"}}, {"cbc:ExecutionRequirementCode": {"@listName": "reserved-execution", "#text": "no"}}], "cac:AwardingTerms": {"cac:AwardingCriterion": {"cac:SubordinateAwardingCriterion": [{"ext:UBLExtensions": {"ext:UBLExtension": {"ext:ExtensionContent": {"efext:EformsExtension": {"efac:AwardCriterionParameter": {"efbc:ParameterCode": {"@listName": "number-weight", "#text": "poi-exa"}, "efbc:ParameterNumeric": "45"}}}}}, "cbc:AwardingCriterionTypeCode": {"@listName": "award-criterion-type", "#text": "quality"}, "cbc:Description": {"@languageID": "FRA", "#text": "1. Valeur technique"}}, {"ext:UBLExtensions": {"ext:UBLExtension": {"ext:ExtensionContent": {"efext:EformsExtension": {"efac:AwardCriterionParameter": {"efbc:ParameterCode": {"@listName": "number-weigh